import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"第四阶段 · 主动服务与手机入口","description":"在有限授权内主动工作，并把手机作为审批和接管入口。","frontmatter":{"title":"第四阶段 · 主动服务与手机入口","description":"在有限授权内主动工作，并把手机作为审批和接管入口。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4.md","filePath":"delivery/stage-4.md","lastUpdated":1793859143000}'),l={name:"delivery/stage-4.md"};function i(h,t,o,s,n,_){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第四阶段-·-主动服务与手机入口" tabindex="-1">第四阶段 · 主动服务与手机入口 <a class="header-anchor" href="#第四阶段-·-主动服务与手机入口" aria-label="Permalink to &quot;第四阶段 · 主动服务与手机入口&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第四阶段让 Hearth 在有限授权内主动工作，并把手机变成查看、审批和接管入口。重点不是“自动运行”，而是在正确的时间做正确的事，并且不制造打扰。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-4/4-1.html">4.1 设置触发条件与主动建议</a></td><td>发现值得处理的事，并解释为什么现在重要。</td></tr><tr><td><a href="/hearth-os/delivery/stage-4/4-2.html">4.2 建立主动收件箱</a></td><td>把建议集中到一个容易判断和处理的地方。</td></tr><tr><td><a href="/hearth-os/delivery/stage-4/4-3.html">4.3 手机查看、审批与接管</a></td><td>手机只保留关键动作和短期权限，丢失后可立即撤销。</td></tr><tr><td><a href="/hearth-os/delivery/stage-4/4-4.html">4.4 控制打扰与验收主动服务</a></td><td>主动模式要安静、有用、可控，并且可以随时关掉。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先建立触发条件和主动建议，不直接自动执行。</li><li>再把建议集中到主动收件箱，让用户决定接受、忽略或转成任务。</li><li>然后交付手机入口，支持查看、审批和接管。</li><li>最后用注意力预算和真实任务验收，确保主动模式安静、可控、可撤销。</li></ol>',7)])])}const m=e(l,[["render",i]]);export{p as __pageData,m as default};
